UPDATE lessons SET title='Year 3, Week 21, Lesson 2: Making a print', data=json_patch(data,'{"child_mission":"To make a print, plan the design on paper first, then draw it lightly into the foam tile with a blunt pencil so the lines are pushed in. Roll a thin layer of paint evenly across the tile, place the paper on top, press with a clean hand or a clean roller, and peel it off slowly. Reprint by re-rolling the paint. Lay prints flat to dry and clean the tile and tools straight away. Press, don''t slide, so the print does not smudge.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same arts idea to a new artwork or performance, then compare two choices for clarity of effect.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nYour first print is patchy and some lines are missing. Name two changes you could make for the next print.\n\nFEEDBACK\nStrong answer: ''Roll the paint more evenly over the whole tile, and press with the flat of my hand all over so the paper touches every part.'' Patchy prints come from uneven paint or uneven pressure.\n\nWATCH FOR\nThinking that sliding the paper makes it stick better. Sliding blurs and smudges the print, so press down firmly without moving the paper.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nDesign and make a foam tile print with a simple picture of your choice, then print it at least four times. Make one in a second colour. Write one sentence about what the repeated prints look like together and what you would change.\n\nWrite a short reflection naming one artistic choice you changed and why. Movement or instrument work is optional, adult-supervised and can be described instead.","interactive_activities":null,"learning_area":"Creative Arts","learning_intention":"To make a print, plan the design on paper first, then draw it lightly into the foam tile with a blunt pencil so the lines are pushed in. Roll a thin layer of paint evenly across the tile, place the paper on top, press with a clean hand or a clean roller, and peel it off slowly. Reprint by re-rolling the paint. Lay prints flat to dry and clean the tile and tools straight away. Press, don''t slide, so the print does not smudge.","lesson_number":2,"lesson_role":"Create and perform","materials":["Paper or typed answer space","Pencil","Optional: scrap paper, crayons, safe classroom instruments or clear movement space with an adult nearby"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["CA2-VIS-01"],"parent_notes":"Parent: Marking guidance for the independent task: Design and make a foam tile print with a simple picture of your choice, then print it at least four times. Make one in a second colour. Write one sentence about what the repeated prints look like together and what you wo Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using a foam tile on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Thinking that sliding the paper makes it stick better.. Correction: Strong answer: ''Roll the paint more evenly over the whole tile, and press with the flat of my hand all over so the. Why it helps the audience is stated.\n\nParent: Likely misconception: Thinking that sliding the paper makes it stick better. Sliding blurs and smudges the print, so press down firmly without moving the paper. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating a foam tile on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with a foam tile, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about a foam tile with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for a foam tile. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":2,"explanation":"This matches the taught method for a foam tile. The other choices miss a key step or use a common mistake.","options":["A claim that names no evidence from the lesson material.","A method that skips the key step taught in this lesson.","''Roll the paint more evenly over the whole tile, and press with the flat of my hand all over so the paper touches every","Thinking that sliding the paper makes it stick better."],"question":"Your first print is patchy and some lines are missing. Name two changes you could make for the next print. Which response is most accurate?","type":"multiple_choice"},{"correct_index":2,"explanation":"This is the misconception to avoid for a foam tile; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["''Roll the paint more evenly over the whole tile, and press with the flat of my hand all over so the paper touches every","Careful use of a roller and explain why it matters with clear evidence.","Thinking that sliding the paper makes it stick better.","To make a print, plan the design on paper first, then draw it lightly into the foam tile with a blunt pencil so the"],"question":"Which statement is a common mistake when working with a foam tile?","type":"multiple_choice"},{"correct_index":3,"explanation":"Understanding is shown by new evidence and a named a roller and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Repeat the worked example wording with no new evidence.","Thinking that sliding the paper makes it stick better.","Name a roller and explain why it matters only, without linking it to a foam tile.","Apply a foam tile to new material and name the a roller and explain why it matters used."],"question":"Which response best applies a foam tile with new evidence?","type":"multiple_choice"},{"correct_index":1,"explanation":"The stronger choice uses elements, techniques and audience effect appropriately for this lesson on a foam tile. The other choices miss a key step or use a common mistake.","options":["Thinking that sliding the paper makes it stick better.","''Roll the paint more evenly over the whole tile, and press with the flat of my hand all over so the paper touches every","Say it looks nice with no element or technique named.","Copy another artwork’s sacred design without permission or guidance."],"question":"Which response best uses elements, techniques and audience effect for a foam tile?","type":"multiple_choice"},{"correct_index":3,"explanation":"Strong answers name specific evidence and what it shows. The other choices miss a key step or use a common mistake.","options":["Say it looks nice with no element or technique named.","Copy another artwork’s sacred design without permission or guidance.","Thinking that sliding the paper makes it stick better.","Name a specific element or technique and say what effect it creates for a foam tile."],"question":"Which evidence move best supports a claim about a foam tile?","type":"multiple_choice"},{"correct_index":1,"explanation":"The stronger choice matches the taught idea with concrete detail. The other choices miss a key step or use a common mistake.","options":["Copy another artwork’s sacred design without permission or guidance.","Example: Max designs a sun with rays.","Thinking that sliding the paper makes it stick better.","Say it looks nice with no element or technique named."],"question":"Using this lesson idea — To make a print, plan the design on paper first, then draw it lightly into the foam tile with a — which choice is best?","type":"multiple_choice"},{"correct_index":3,"explanation":"Accuracy means checking evidence and honouring limits or protocols. The other choices miss a key step or use a common mistake.","options":["Invent missing details to make the answer sound complete.","Ignore safety or cultural protocols to finish faster.","Treat every claim as equally reliable without checking a source or cue.","Name the artistic choice, its effect, and keep cultural protocols respectful."],"question":"Which action keeps elements, techniques and audience effect accurate for a foam tile?","type":"multiple_choice"},{"correct_index":2,"explanation":"Independence requires a new example that still uses the taught skill. The other choices miss a key step or use a common mistake.","options":["Thinking that sliding the paper makes it stick better.","Name a roller and explain why it matters only, with no linked example.","Design and make a foam tile print with a simple picture of your choice, then print it at least four times.","Retype the worked example with no new example."],"question":"Which independent response best applies a foam tile to new material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about a foam tile with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating a foam tile on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using a foam tile on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for a foam tile. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with a foam tile, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Thinking that sliding the paper makes it stick better.. Correction: Strong answer: ''Roll the paint more evenly over the whole tile, and press with the flat of my hand all over so the. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent artwork or performance notes and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-arts-y3-w21-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA Creative Arts alignment using catalogue outcome codes (CA2-*); content-point mapping remains pending. First Nations arts content requires local Aboriginal educator or Custodian guidance before acceptance; do not invent sacred designs.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise a foam tile.","Read the mission before you start making or performing.","Keep the audience effect of your choice in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not name an effect clearly."],"learn":["Study how the first demonstration is built.","Point to the element or technique that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore elements, safety or respectful practice.","Prefer a named artistic reason over a guess that merely looks colourful."],"submit":["Confirm that your choice and reason are both present.","Proofread element names and safety notes.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact element, technique or cue before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key artistic choices.","Say what each choice does for the artwork or audience.","A final praise word alone is weaker than a named effect."],"teach2":["Compare a weak choice with a stronger one.","Change the element or technique, not only the decoration.","Name the mistake you are repairing."],"teach3":["Choose a fresh subject or piece that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original work notes and a short reflection.","Save work that shows the skill on new material."]},"subject":"Visual Arts","success_criteria":["I can use a foam tile with a specific example from this lesson.","I can identify a roller and explain why it matters.","I can practise a clean print independently on a new prompt.","I can notice a drying space needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":3,"explanation":"To make a print, plan the design on paper first, then draw it lightly into the foam tile with a blunt pencil so the lines are pushed in.","options":["A comment that only says it looks nice with no element named.","An answer copied without understanding.","A guess with no artistic reason.","To make a print, plan the design on paper first, then draw it lightly into the foam tile with a blunt pencil so the"],"question":"Which choice best applies this lesson idea about a foam tile with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: Max designs a sun with rays. He pushes the lines into the foam. He rolls yellow on the tile, presses it onto card and lifts it slowly. The first print is light, so he adds a little more paint and prints again. The second print is bold and clear, so he makes a row of four and lays them flat to dry on a tray.\n\nTRY FIRST\nYour first print is patchy and some lines are missing. Name two changes you could make for the next print.\n\nFEEDBACK\nStrong answer: ''Roll the paint more evenly over the whole tile, and press with the flat of my hand all over so the paper touches every part.'' Patchy prints come from uneven paint or uneven pressure.","explain":"To make a print, plan the design on paper first, then draw it lightly into the foam tile with a blunt pencil so the lines are pushed in. Roll a thin layer of paint evenly across the tile, place the paper on top, press with a clean hand or a clean roller, and peel it off slowly. Reprint by re-rolling the paint. Lay prints flat to dry and clean the tile and tools straight away. Press, don''t slide, so the print does not smudge.\n\nWHY IT MATTERS\nThis helps the learner make intentional visual, music, drama or dance choices and name their effect, rather than saying an artwork is simply “nice”. Keep every claim linked to an element or technique.\n\nHOW TO WORK\nRead the worked example and name the elements, techniques or performance choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For movement or instruments, use a clear space, ask an adult to be nearby and stop if anything feels unsafe. You may always describe a choice instead of performing it. One deliberate artistic choice with a named effect is more useful than a longer praise sentence.","icon":"📖","notice":"Thinking that sliding the paper makes it stick better. Sliding blurs and smudges the print, so press down firmly without moving the paper. Name the element or technique and its effect, not just decoration.","title":"Understand and demonstrate","visual":[{"alt":"Rolling and pressing.","caption":"Press, do not slide.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Roll</text><text x=\"28\" y=\"78\">even thin paint</text><text x=\"358\" y=\"42\">Press</text><text x=\"358\" y=\"78\">flat hand, no sliding</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which artistic choice matters most.","who":"pip"},{"text":"Name the element, technique or performance choice and the effect it creates before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Example: Max designs a sun with rays. He pushes the lines into the foam. He rolls yellow on the tile, presses it onto ca Then write your own artistic reason.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which artistic choice matters most.\nJuno: Name the element, technique or performance choice and the effect it creates before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Example: Max designs a sun with rays. He pushes the lines into the foam. He rolls yellow on the tile, presses it onto ca Then write your own artistic reason."}}]},{"check":{"correct_index":0,"explanation":"Make the arts idea visible: name the element, technique or performance choice you used and say what effect it creates. Supported responses name the element or technique and its effect. Apply the lesson idea with evidence. The other choices miss a key step or use a common mistake.","options":["Make the arts idea visible: name the element, technique or performance choice you used and say what effect it creates.","A comment that only says it looks nice with no element named.","An answer copied without understanding.","A guess with no artistic reason."],"question":"Which choice best applies this lesson idea about a foam tile with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: Max designs a sun with rays. He pushes the lines into the foam. He rolls yellow on the tile, presses it onto card and lifts it slowly. The first print is light, so he adds a little more paint and prints again. The second print is bold and clear, so he makes a row of four and lays them flat to dry on a tray. Look at each line, sound, movement or role choice that carries the idea.\n\nTRY FIRST\nList the key artistic choices from the example and say what each one does for the audience or artwork.\n\nFEEDBACK\nThe most useful response names the element or technique and its effect, not only “it looks nice”.","explain":"Make the arts idea visible: name the element, technique or performance choice you used and say what effect it creates.\n\nWHY IT MATTERS\nThis helps the learner make intentional visual, music, drama or dance choices and name their effect, rather than saying an artwork is simply “nice”. Keep every claim linked to an element or technique.\n\nHOW TO WORK\nRead the worked example and name the elements, techniques or performance choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For movement or instruments, use a clear space, ask an adult to be nearby and stop if anything feels unsafe. You may always describe a choice instead of performing it. One deliberate artistic choice with a named effect is more useful than a longer praise sentence.","icon":"📖","notice":"Writing only a final praise word without naming a choice does not show arts thinking. Name the element or technique and its effect, not just decoration.","title":"Show the artistic choice","visual":[{"alt":"Patchy and clear prints.","caption":"Fix the paint and press.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Patchy</text><text x=\"28\" y=\"78\">uneven paint</text><text x=\"358\" y=\"42\">Clear</text><text x=\"358\" y=\"78\">even paint and pressure</text></g></svg>"}]},{"check":{"correct_index":1,"explanation":"Use an intentionally weak or disrespectful arts choice as a comparison.","options":["An answer copied without understanding.","Use an intentionally weak or disrespectful arts choice as a comparison.","A guess with no artistic reason.","A comment that only says it looks nice with no element named."],"question":"Which choice best applies this lesson idea about a foam tile with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nThinking that sliding the paper makes it stick better. Sliding blurs and smudges the print, so press down firmly without moving the paper. Here is a more helpful example: Example: Max designs a sun with rays. He pushes the lines into the foam. He rolls yellow on the tile, presses it onto card and lifts it slowly. The first print is light, so he adds a little more paint and prints again. The second print is bold and clear, so he makes a row of four and lays them flat to dry on a tray.\n\nTRY FIRST\nDescribe why the warned-against choice weakens the work, then write a stronger choice with a reason.\n\nFEEDBACK\nStrong answer: ''Roll the paint more evenly over the whole tile, and press with the flat of my hand all over so the paper touches every part.'' Patchy prints come from uneven paint or uneven pressure.","explain":"Use an intentionally weak or disrespectful arts choice as a comparison. Name the specific error, then show a clearer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make intentional visual, music, drama or dance choices and name their effect, rather than saying an artwork is simply “nice”. Keep every claim linked to an element or technique.\n\nHOW TO WORK\nRead the worked example and name the elements, techniques or performance choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For movement or instruments, use a clear space, ask an adult to be nearby and stop if anything feels unsafe. You may always describe a choice instead of performing it. One deliberate artistic choice with a named effect is more useful than a longer praise sentence.","icon":"📖","notice":"Changing the decoration without changing the artistic idea does not fix the error. Thinking that sliding the paper makes it stick better. Sliding blurs and smudges the print, so press down firmly without moving the paper. Name the element or technique and its effect, not just decoration.","title":"Test a misconception"},{"check":{"correct_index":1,"explanation":"Use the same arts idea in a new artwork, song, drama or dance, not a copy of the example.","options":["An answer copied without understanding.","Use the same arts idea in a new artwork, song, drama or dance, not a copy of the example.","A guess with no artistic reason.","A comment that only says it looks nice with no element named."],"question":"Which choice best applies this lesson idea about a foam tile with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nTo make a print, plan the design on paper first, then draw it lightly into the foam tile with a blunt pencil so the lines are pushed in. Roll a thin layer of paint evenly across the tile, place the paper on top, press with a clean hand or a clean roller, and peel it off slowly. Reprint by re-rolling the paint. Lay prints flat to dry and clean the tile and tools straight away. Press, don''t slide, so the print does not smudge. Now choose a different subject or piece to show you can transfer the idea.\n\nTRY FIRST\nMake or describe one fresh example that uses the same skill and write a short reason for your main choice.\n\nFEEDBACK\nThe new example should use the same arts idea as the model, but with different content or material.","explain":"Use the same arts idea in a new artwork, song, drama or dance, not a copy of the example. Review clarity, safety and respectful practice.\n\nWHY IT MATTERS\nThis helps the learner make intentional visual, music, drama or dance choices and name their effect, rather than saying an artwork is simply “nice”. Keep every claim linked to an element or technique.\n\nHOW TO WORK\nRead the worked example and name the elements, techniques or performance choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For movement or instruments, use a clear space, ask an adult to be nearby and stop if anything feels unsafe. You may always describe a choice instead of performing it. One deliberate artistic choice with a named effect is more useful than a longer praise sentence.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new artwork or performance. Name the element or technique and its effect, not just decoration.","title":"Transfer to a new artwork or performance"}],"title":"Year 3, Week 21, Lesson 2: Making a print","unit_number":5,"unit_title":"Printmaking, collage and texture","week":21,"week_in_unit":1,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample: Max designs a sun with rays. He pushes the lines into the foam. He rolls yellow on the tile, presses it onto card and lifts it slowly. The first print is light, so he adds a little more paint and prints again. The second print is bold and clear, so he makes a row of four and lays them flat to dry on a tray.\n\nWrite what makes this example effective, naming the element, technique or performance choice and its effect.","worked_visuals":[{"alt":"Rolling and pressing.","caption":"Press, do not slide.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Roll</text><text x=\"28\" y=\"78\">even thin paint</text><text x=\"358\" y=\"42\">Press</text><text x=\"358\" y=\"78\">flat hand, no sliding</text></g></svg>"},{"alt":"Patchy and clear prints.","caption":"Fix the paint and press.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Patchy</text><text x=\"28\" y=\"78\">uneven paint</text><text x=\"358\" y=\"42\">Clear</text><text x=\"358\" y=\"78\">even paint and pressure</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-arts-y3-w21-l2' AND family_id IS NULL;
